#!/usr/bin/env node
// Fake Claude Code for E2E tests. The command line matches the
// `@anthropic-ai/claude-code` agent rule; the session registry file and OSC 9;4 progress follow stdin commands:
//   work → busy + OSC 9;4;3   ask [seconds] → waiting (permission) + BEL   done → idle + OSC 9;4;0   quit → exit
//   hook <Event> [notification_type] → runs the `http` hooks of $FAKE_CLAUDE_HOOKS (a hooks.json) like Claude Code:
//   POST the hook input as JSON, header values interpolated from `allowedEnvVars` only. For `UserPromptSubmit` the
//   rest of the line is the prompt; with $FAKE_CLAUDE_HOOK_OUT every response is appended to that file as a JSON line
//   `{ event, status, body }` (the hook's JSON output, e.g. `additionalContext`, without terminal line wrapping).
//   exitplan <text> → finishes a plan: runs the `PreToolUse` `ExitPlanMode` http hooks of the `--settings` file (" | "
//   in the text becomes a line break); a "deny" prints "PLAN HANDED OVER", no decision prints Claude's usual question.
//   anything else → a prompt: printed as "PROMPT: <text>", busy for half a second, then idle again.
// The arguments are printed at start ("ARGS: …"); a positional argument is the first prompt, like `claude "…"`.
// `exitplan` waits for the hook's answer as long as Oxytocin takes (Task holds it until the user decides).
'use strict';
const fs = require('node:fs');
const path = require('node:path');
const os = require('node:os');
const readline = require('node:readline');

const configDir = process.env.CLAUDE_CONFIG_DIR || path.join(os.homedir(), '.claude');
const sessionsDir = path.join(configDir, 'sessions');
const file = path.join(sessionsDir, `${process.pid}.json`);
const sessionId = `fake-${process.pid}`;

function writeStatus(status, extra) {
  fs.mkdirSync(sessionsDir, { recursive: true });
  const entry = { pid: process.pid, sessionId, cwd: process.cwd(), name: 'Fake session', status, updatedAt: Date.now(), ...extra };
  fs.writeFileSync(`${file}.tmp`, JSON.stringify(entry));
  fs.renameSync(`${file}.tmp`, file);
}

function cleanup() {
  try {
    fs.unlinkSync(file);
  } catch {
    // already gone
  }
}

const ESC = '\x1b';
const prompt = () => process.stdout.write('fake-claude> ');
writeStatus('idle');
const args = process.argv.slice(2);
const VALUE_FLAGS = new Set(['--permission-mode', '--model', '--effort', '--settings', '--add-dir']);
const firstPrompt = args.find((a, i) => !a.startsWith('-') && !VALUE_FLAGS.has(args[i - 1]));
process.stdout.write(`ARGS: ${args.join(' ')}\r\n`);
process.stdout.write('Fake Claude Code ready\r\n');
if (firstPrompt) {
  process.stdout.write(`PROMPT: ${firstPrompt}\r\n`);
  writeStatus('busy');
  setTimeout(() => {
    writeStatus('idle');
    prompt();
  }, 500);
} else prompt();

const rl = readline.createInterface({ input: process.stdin });
function ask() {
  writeStatus('waiting', { waitingFor: 'permission' });
  process.stdout.write('Allow tool use? \x07\r\n');
}

async function runHooks(event, notificationType, prompt) {
  const config = JSON.parse(fs.readFileSync(process.env.FAKE_CLAUDE_HOOKS, 'utf8'));
  const input = { session_id: sessionId, transcript_path: '', cwd: process.cwd(), hook_event_name: event };
  if (notificationType) Object.assign(input, { notification_type: notificationType, message: 'Claude needs your permission' });
  if (event === 'UserPromptSubmit') input.prompt = prompt || 'secret prompt text';
  for (const group of config.hooks[event] || []) {
    for (const hook of group.hooks) {
      if (hook.type !== 'http') continue;
      const allowed = new Set(hook.allowedEnvVars || []);
      const headers = { 'content-type': 'application/json' };
      for (const [name, value] of Object.entries(hook.headers || {}))
        headers[name] = value.replace(/\$\{?([A-Z0-9_]+)\}?/g, (_m, v) => (allowed.has(v) ? process.env[v] || '' : ''));
      try {
        const res = await fetch(hook.url, { method: 'POST', headers, body: JSON.stringify(input) });
        const body = await res.text();
        if (process.env.FAKE_CLAUDE_HOOK_OUT)
          fs.appendFileSync(process.env.FAKE_CLAUDE_HOOK_OUT, `${JSON.stringify({ event, status: res.status, body })}\n`);
        process.stdout.write(`hook ${event} ${res.status}\r\n`);
      } catch (e) {
        process.stdout.write(`hook ${event} failed: ${e.message}\r\n`);
      }
    }
  }
}

const interpolate = (hook, value) =>
  value.replace(/\$\{?([A-Z0-9_]+)\}?/g, (_m, v) => ((hook.allowedEnvVars || []).includes(v) ? process.env[v] || '' : ''));

async function exitPlan(plan) {
  const at = args.indexOf('--settings');
  const settings = at === -1 ? {} : JSON.parse(fs.readFileSync(args[at + 1], 'utf8'));
  const input = {
    session_id: sessionId,
    transcript_path: '',
    cwd: process.cwd(),
    hook_event_name: 'PreToolUse',
    tool_name: 'ExitPlanMode',
    tool_input: { plan, planFilePath: path.join(configDir, 'plans', 'fake-plan.md') },
  };
  let denied = false;
  for (const group of (settings.hooks && settings.hooks.PreToolUse) || []) {
    if (group.matcher !== 'ExitPlanMode') continue;
    for (const hook of group.hooks) {
      if (hook.type !== 'http') continue;
      const headers = { 'content-type': 'application/json' };
      for (const [name, value] of Object.entries(hook.headers || {})) headers[name] = interpolate(hook, value);
      try {
        const res = await fetch(hook.url, { method: 'POST', headers, body: JSON.stringify(input) });
        const text = res.status === 200 ? await res.text() : '';
        const output = text.trim() ? JSON.parse(text) : null;
        if (output && output.hookSpecificOutput && output.hookSpecificOutput.permissionDecision === 'deny') {
          denied = true;
          process.stdout.write(`PLAN HANDED OVER: ${output.hookSpecificOutput.permissionDecisionReason}\r\n`);
        }
      } catch (e) {
        process.stdout.write(`PreToolUse:ExitPlanMode hook error: ${e.message}\r\n`);
      }
    }
  }
  if (!denied) process.stdout.write('Claude has written up a plan and is ready to execute. Would you like to proceed?\r\n');
}

rl.on('line', (line) => {
  const [cmd, arg] = line.trim().split(/\s+/);
  if (cmd === 'hook') {
    const words = line.trim().split(/\s+/);
    const isPrompt = arg === 'UserPromptSubmit';
    void runHooks(arg, isPrompt ? undefined : words[2], isPrompt ? words.slice(2).join(' ') : undefined).then(prompt);
    return;
  }
  if (cmd === 'exitplan') {
    writeStatus('busy');
    const plan = line.trim().slice('exitplan'.length).trim().split(' | ').join('\n');
    void exitPlan(plan).then(() => {
      writeStatus('idle');
      prompt();
    });
    return;
  }
  if (cmd === 'work') {
    writeStatus('busy');
    process.stdout.write(`${ESC}]9;4;3${ESC}\\working…\r\n`);
  } else if (cmd === 'ask') {
    // `ask 3` asks after 3 s (lets a test switch to another project first).
    if (arg) setTimeout(ask, Number(arg) * 1000);
    else ask();
  } else if (cmd === 'done') {
    writeStatus('idle');
    process.stdout.write(`${ESC}]9;4;0${ESC}\\done\r\n`);
  } else if (cmd === 'quit') {
    cleanup();
    process.exit(0);
  } else if (line.trim()) {
    process.stdout.write(`PROMPT: ${line.trim()}\r\n`);
    writeStatus('busy');
    setTimeout(() => {
      writeStatus('idle');
      prompt();
    }, 500);
    return;
  }
  prompt();
});
process.on('SIGINT', () => {
  cleanup();
  process.exit(130);
});
process.on('SIGTERM', () => {
  cleanup();
  process.exit(143);
});
rl.on('close', () => {
  cleanup();
  process.exit(0);
});
